<script setup lang="ts">
import { computed,onMounted,reactive,ref,watch } from 'vue'
import type { CatalogoSimple,DocumentoProveedor,DocumentoProveedorFiltros,DocumentoProveedorPayload,ProveedorFinanzas } from '../interfaces/documento-proveedor.interface'
import { buscarProveedorDocumento,cambiarEstadoDocumentoProveedor,catalogosDetraccionDocumento,guardarDocumentoProveedor,listarDocumentosProveedor,obtenerDocumentoProveedor,opcionesDocumentoProveedor } from '../services/documento-proveedor'
const today=new Date().toISOString().slice(0,10),blankFilters=():DocumentoProveedorFiltros=>({proveedor:'',tipo_documento_id:'',estado:'',numero_documento:'',fecha_desde:'',fecha_hasta:''}),blankForm=():DocumentoProveedorPayload=>({proveedor_id:0,tipo_documento_id:0,serie:'',numero:'',fecha_emision:today,fecha_vencimiento:'',moneda_id:0,tipo_cambio:1,base_imponible:0,impuesto:0,importe_inafecto:0,otros_importes:0,importe_total:0,aplica_retencion:false,aplica_detraccion:false,catalogo_detraccion_id:null,glosa:''})
const filters=reactive(blankFilters()),form=reactive(blankForm()),rows=ref<DocumentoProveedor[]>([]),types=ref<CatalogoSimple[]>([]),currencies=ref<CatalogoSimple[]>([]),deductions=ref<CatalogoSimple[]>([]),providers=ref<ProveedorFinanzas[]>([]),provider=ref<ProveedorFinanzas|null>(null),providerQuery=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),error=ref(''),success=ref(''),showForm=ref(false),editing=ref<number|null>(null),detail=ref<DocumentoProveedor|null>(null)
const calculated=computed(()=>Number(form.base_imponible||0)+Number(form.impuesto||0)+Number(form.importe_inafecto||0)+Number(form.otros_importes||0)),message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.',money=(v:number)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(v||0)),date=(v?:string|null)=>v?new Date(`${v.slice(0,10)}T00:00:00`).toLocaleDateString('es-PE'):'-'
async function load(next=1){loading.value=true;error.value='';try{const r=await listarDocumentosProveedor(filters,next);rows.value=r.data;types.value=r.tipos_documento||types.value;currencies.value=r.monedas||currencies.value;page.value=r.current_page;lastPage.value=r.last_page;total.value=r.total}catch(e){error.value=message(e)}finally{loading.value=false}}
async function searchProvider(){if(providerQuery.value.length<4)return;try{providers.value=await buscarProveedorDocumento(providerQuery.value)}catch(e){error.value=message(e)}}
function selectProvider(x:ProveedorFinanzas){provider.value=x;form.proveedor_id=x.id;providerQuery.value=`${x.ruc} - ${x.razon_social}`;providers.value=[]}
async function refreshDeductions(){try{deductions.value=await catalogosDetraccionDocumento(form.fecha_emision)}catch{deductions.value=[]}}
function create(){editing.value=null;provider.value=null;providerQuery.value='';Object.assign(form,blankForm());showForm.value=true;refreshDeductions()}
async function edit(item:DocumentoProveedor){loading.value=true;try{const x=await obtenerDocumentoProveedor(item.id);editing.value=x.id;provider.value={id:x.proveedor_id,ruc:x.proveedor_numero_documento,razon_social:x.proveedor_razon_social};providerQuery.value=`${x.proveedor_numero_documento} - ${x.proveedor_razon_social}`;Object.assign(form,blankForm(),x,{fecha_emision:x.fecha_emision.slice(0,10),fecha_vencimiento:x.fecha_vencimiento?.slice(0,10)||'',catalogo_detraccion_id:x.detraccion?.catalogo_detraccion_id||null});showForm.value=true;await refreshDeductions()}catch(e){error.value=message(e)}finally{loading.value=false}}
async function view(item:DocumentoProveedor){loading.value=true;try{detail.value=await obtenerDocumentoProveedor(item.id)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function save(){if(form.fecha_vencimiento&&form.fecha_vencimiento<form.fecha_emision){error.value='El vencimiento no puede ser anterior a la emisión.';return}if(Math.abs(calculated.value-form.importe_total)>.01&&calculated.value>0){error.value='El importe total no coincide con la suma de sus componentes.';return}loading.value=true;error.value='';try{await guardarDocumentoProveedor(editing.value,{...form});success.value=`Documento ${editing.value?'actualizado':'registrado'} correctamente.`;showForm.value=false;await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function toggle(item:DocumentoProveedor){if(!confirm(`¿Desea ${item.estado==='ANULADO'?'activar':'anular'} este documento?`))return;loading.value=true;try{await cambiarEstadoDocumentoProveedor(item.id);success.value='Estado actualizado correctamente.';await load(page.value)}catch(e){error.value=message(e)}finally{loading.value=false}}
function clear(){Object.assign(filters,blankFilters());load(1)}
watch(()=>form.fecha_emision,refreshDeductions);watch(calculated,v=>{form.importe_total=Number(v.toFixed(4))})
onMounted(async()=>{try{const x=await opcionesDocumentoProveedor(today);types.value=x.tipos_documento;currencies.value=x.monedas;deductions.value=x.catalogo_detracciones}catch(e){error.value=message(e)}await load()})
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Finanzas / Documentos de proveedores</nav><header class="hero"><div class="mark">DP</div><div><small>MIA · FINANZAS · PROVEEDORES</small><h1>Documentos de proveedores</h1><p>Registro y control de documentos pendientes, retenciones y detracciones.</p></div><strong>{{total}} documentos</strong><button @click="create">+ Nuevo documento</button></header><p v-if="error" class="flash badmsg">{{error}}</p><p v-if="success" class="flash okmsg">{{success}}</p><form class="filters" @submit.prevent="load(1)"><input v-model.trim="filters.proveedor" placeholder="RUC o proveedor"><select v-model="filters.tipo_documento_id"><option value="">Todos los tipos</option><option v-for="x in types" :key="x.id" :value="x.id">{{x.nombre||x.descripcion}}</option></select><select v-model="filters.estado"><option value="">Todos los estados</option><option>PENDIENTE</option><option>PAGADO</option><option>ANULADO</option></select><input v-model.trim="filters.numero_documento" placeholder="Serie o número"><input v-model="filters.fecha_desde" type="date"><input v-model="filters.fecha_hasta" type="date"><button>Filtrar</button><button type="button" class="soft" @click="clear">Limpiar</button></form><section class="card"><div v-if="loading" class="empty">Procesando…</div><div v-else-if="!rows.length" class="empty">No se encontraron documentos.</div><div v-else class="scroll"><table><thead><tr><th>Documento</th><th>Proveedor</th><th>Emisión / vencimiento</th><th>Moneda</th><th>Importe</th><th>Obligaciones</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><b>{{item.numero_documento_completo||`${item.serie}-${item.numero}`}}</b><small>{{item.tipo_documento?.nombre||item.tipo_documento?.descripcion}}</small></td><td><b>{{item.proveedor_numero_documento}}</b><small>{{item.proveedor_razon_social}}</small></td><td>{{date(item.fecha_emision)}}<small>Vence: {{date(item.fecha_vencimiento)}}</small></td><td>{{item.moneda?.nombre}}<small>TC: {{item.tipo_cambio}}</small></td><td class="number"><b>{{money(item.importe_total)}}</b></td><td><span v-if="item.aplica_retencion" class="tag">RETENCIÓN</span><span v-if="item.aplica_detraccion" class="tag det">DETRACCIÓN</span></td><td><span :class="item.estado==='PENDIENTE'?'warn':item.estado==='PAGADO'?'good':'bad'">{{item.estado}}</span></td><td class="actions"><button @click="view(item)">Ver</button><button v-if="item.estado==='PENDIENTE'" class="edit" @click="edit(item)">Editar</button><button v-if="item.estado!=='PAGADO'" class="danger" @click="toggle(item)">{{item.estado==='ANULADO'?'Activar':'Anular'}}</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="showForm" class="backdrop" @mousedown.self="showForm=false"><form class="dialog" @submit.prevent="save"><header><div><small>{{editing?'EDICIÓN':'NUEVO DOCUMENTO'}}</small><h2>{{editing?'Editar':'Registrar'}} documento</h2></div><button type="button" @click="showForm=false">×</button></header><div class="provider-search"><label>Proveedor<input v-model.trim="providerQuery" required placeholder="Buscar RUC o razón social" @input="searchProvider"></label><ul v-if="providers.length"><li v-for="x in providers" :key="x.id" @click="selectProvider(x)"><b>{{x.ruc}}</b> {{x.razon_social}}</li></ul></div><div class="grid"><label>Tipo de documento<select v-model.number="form.tipo_documento_id" required><option :value="0">Seleccione</option><option v-for="x in types" :key="x.id" :value="x.id">{{x.nombre||x.descripcion}}</option></select></label><label>Serie<input v-model.trim="form.serie" maxlength="20"></label><label>Número<input v-model.trim="form.numero" maxlength="30" required></label><label>Moneda<select v-model.number="form.moneda_id" required><option :value="0">Seleccione</option><option v-for="x in currencies" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Fecha de emisión<input v-model="form.fecha_emision" type="date" required></label><label>Fecha de vencimiento<input v-model="form.fecha_vencimiento" type="date"></label><label>Tipo de cambio<input v-model.number="form.tipo_cambio" type="number" min=".000001" step=".000001" required></label><label>Base imponible<input v-model.number="form.base_imponible" type="number" min="0" step=".0001"></label><label>Impuesto<input v-model.number="form.impuesto" type="number" min="0" step=".0001"></label><label>Importe inafecto<input v-model.number="form.importe_inafecto" type="number" min="0" step=".0001"></label><label>Otros importes<input v-model.number="form.otros_importes" type="number" min="0" step=".0001"></label><label>Total calculado<input v-model.number="form.importe_total" type="number" min=".0001" step=".0001" required></label><label class="span2">Glosa<textarea v-model.trim="form.glosa" maxlength="2000"></textarea></label></div><div class="checks"><label><input v-model="form.aplica_retencion" type="checkbox"> Aplica retención</label><label><input v-model="form.aplica_detraccion" type="checkbox"> Aplica detracción</label></div><label v-if="form.aplica_detraccion" class="deduction">Catálogo de detracción<select v-model.number="form.catalogo_detraccion_id" required><option :value="null">Seleccione</option><option v-for="x in deductions" :key="x.id" :value="x.id">{{x.text||`${x.codigo} - ${x.descripcion} (${x.porcentaje}%)`}}</option></select></label><footer><button type="button" class="soft" @click="showForm=false">Cancelar</button><button :disabled="loading||!form.proveedor_id">Guardar</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="dialog detail"><header><div><small>DOCUMENTO #{{detail.id}}</small><h2>{{detail.numero_documento_completo||`${detail.serie}-${detail.numero}`}}</h2></div><span :class="detail.estado==='PAGADO'?'good':detail.estado==='ANULADO'?'bad':'warn'">{{detail.estado}}</span><button @click="detail=null">×</button></header><div class="facts"><div><small>PROVEEDOR</small><b>{{detail.proveedor_numero_documento}} · {{detail.proveedor_razon_social}}</b></div><div><small>EMISIÓN / VENCIMIENTO</small><b>{{date(detail.fecha_emision)}} · {{date(detail.fecha_vencimiento)}}</b></div><div><small>IMPORTE TOTAL</small><b>{{money(detail.importe_total)}}</b></div></div><h3>Detalle de importes</h3><p>Base {{money(detail.base_imponible)}} · Impuesto {{money(detail.impuesto)}} · Inafecto {{money(detail.importe_inafecto)}} · Otros {{money(detail.otros_importes)}}</p><h3>Glosa</h3><p>{{detail.glosa||'Sin glosa'}}</p><h3>Archivos ({{detail.archivos?.length||0}})</h3><ul><li v-for="x in detail.archivos" :key="x.id">{{x.archivo_original}} · {{x.tipo_archivo}} <b v-if="x.principal">(Principal)</b></li></ul></section></div></div></template>
<style scoped>
.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;color:#91a0a5;font-size:.68rem}nav a{color:var(--a)}.hero{display:flex;align-items:center;gap:14px;padding:20px;border-left:5px solid var(--a);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a);font-weight:800}.hero>div:nth-child(2){flex:1}.hero small,.dialog small,.facts small{color:var(--a);font-size:.49rem;font-weight:800}.hero h1{margin:3px 0;font-size:1.3rem}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero strong{font-size:.55rem}button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;cursor:pointer}.soft{color:#607078;background:#edf2f3}.flash{padding:10px;border-radius:6px;font-size:.55rem}.badmsg{color:#9b3d48;background:#fdebee}.okmsg{color:#236c50;background:#e8f7ee}.filters{margin-top:11px;padding:13px;display:grid;grid-template-columns:1.5fr 1.2fr 1fr 1fr 1fr 1fr auto auto;gap:7px;background:#fff}.filters input,.filters select,.dialog input,.dialog select,.dialog textarea{box-sizing:border-box;width:100%;padding:8px;border:1px solid #d5dfe2;border-radius:6px;background:#fff;font-size:.5rem}.card{margin-top:11px;background:#fff}.scroll{overflow:auto}table{width:100%;min-width:1150px;border-collapse:collapse;font-size:.49rem}th,td{padding:9px;border-bottom:1px solid #e3e9eb;text-align:left;vertical-align:top}th{color:#fff;background:#435d6c}td small{display:block;margin-top:3px;color:#829096}.number{text-align:right}.good,.bad,.warn,.tag{display:inline-block;margin:1px;padding:4px 7px;border-radius:10px;font-size:.44rem;font-weight:800}.good{color:#267153;background:#e5f7ec}.bad{color:#9d414a;background:#fdebed}.warn{color:#886113;background:#fff2d3}.tag{color:#3d6171;background:#e5f0f4}.tag.det{color:#76530e;background:#fff0c7}.actions{display:flex;gap:4px}.edit{background:#c98a24}.danger{background:#b74b54}.empty{padding:55px;text-align:center}.card>footer,.dialog>footer{padding:12px;display:flex;justify-content:center;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(850px,100%);max-height:93vh;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff;overflow:auto}.dialog>header{display:flex;gap:10px}.dialog>header div{flex:1}.dialog h2{margin:3px 0 15px}.dialog>header button{color:#66757b;background:none;font-size:1.2rem}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:9px}.grid label,.provider-search label,.deduction{display:grid;gap:4px;color:#5d7078;font-size:.5rem;font-weight:700}.span2{grid-column:span 2}.dialog textarea{min-height:55px}.checks{display:flex;gap:20px;margin:13px 0;font-size:.5rem}.provider-search{position:relative;margin-bottom:10px}.provider-search ul{position:absolute;z-index:4;width:100%;margin:2px 0;padding:0;border:1px solid #ddd;background:#fff;list-style:none}.provider-search li{padding:8px;font-size:.5rem;cursor:pointer}.facts{display:grid;grid-template-columns:2fr 1fr 1fr;gap:8px}.facts div{display:grid;gap:4px;padding:10px;background:#f1f6f7}.detail h3{margin:17px 0 5px;font-size:.65rem}.detail p,.detail li{font-size:.54rem}@media(max-width:900px){.filters{grid-template-columns:repeat(3,1fr)}.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.filters,.grid,.facts{grid-template-columns:1fr}.span2{grid-column:auto}.hero{flex-wrap:wrap}.hero .mark{display:none}}
</style>
